INSERT INTO `dict_entry` (`id`, `lemma`, `phonetic_us`, `phonetic_uk`, `audio_us`, `audio_uk`, `pos`, `definition_cn`, `definition_en`, `tags`, `frequency_rank`, `sample_sentence`, `sample_translation`)
VALUES
(2, 'create', '/kriˈeɪt/', '/kriˈeɪt/', 'NULL', 'NULL', 'v.', 'v. 创造；构建；引发', 'to bring something into existence', 'CET4,CET6', 450, 'She created a wonderful piece of art.', '她创作了一幅极棒的艺术作品。'),
(3, 'design', '/dɪˈzaɪn/', '/dɪˈzaɪn/', 'NULL', 'NULL', 'n./v.', 'n. 设计；架构构想 v. 构思；筹划', 'to plan or produce something for a specific purpose', 'CET4,CET6', 620, 'Good design makes things simple and intuitive.', '好的设计能让事物简明且符合直觉。'),
(7, 'data', '/ˈdeɪtə/', '/ˈdeɪtə/', 'NULL', 'NULL', 'n.', 'n. 数据；记忆指标追踪', 'facts and statistics collected together for reference', 'CET4,CET6', 180, 'The learning data provides clear visual feedback.', '学习数据提供了清晰的可视化反馈。'),
(10, 'technology', '/tekˈnɑːlədʒi/', '/tekˈnɒlədʒi/', 'NULL', 'NULL', 'n.', 'n. 语音智能；声学技术', 'the application of scientific knowledge for practical purposes', 'CET4,CET6', 420, 'Modern technology changes the way we learn languages.', '现代科技改变了我们学习语言的方式。'),
(12, 'future', '/ˈfjuːtʃər/', '/ˈfjuːtʃə/', 'NULL', 'NULL', 'n./adj.', 'n. 未来；前景 adj. 未来的', 'a period of time following the moment of speaking', 'CET4', 380, 'The future of language acquisition is multimodal and contextual.', '下一代语言习得的未来是多模态且深嵌语境的。'),
(24, 'nuance', '/ˈnuːɑːns/', '/ˈnjuːɑːns/', 'NULL', 'NULL', 'n.', 'n. 细微差别；语气微妙之处', 'a subtle difference in or shade of meaning, expression, or sound', 'CET6,IELTS', 3400, 'Context snapshots help you perceive subtle emotional nuances.', '语境快照有助于研习者捕捉微妙的情感语气细微差别。'),
(25, 'ubiquitous', '/juːˈbɪkwɪtəs/', '/juːˈbɪkwɪtəs/', 'NULL', 'NULL', 'adj.', 'adj. 无所不在的；普遍存在的', 'present, appearing, or found everywhere', 'CET6,GRE', 4800, 'English media is ubiquitous in our modern connected world.', '英语媒体在我们当今互联的世界中几乎无处不在。'),
(29, 'paradigm', '/ˈpærədaɪm/', '/ˈpærədaɪm/', 'NULL', 'NULL', 'n.', 'n. 范式；认知模型', 'a typical example or pattern of something; a model', 'CET6,IELTS', 3100, 'We need to postulate a completely different paradigm to explain all these phenomena.', '要说明所有这些现象，就需要用完全不同示例。'),
(30, 'synergy', '/ˈsɪnərdʒi/', '/ˈsɪnədʒi/', 'NULL', 'NULL', 'n.', 'n. 协同效应；增效作用', 'the interaction of elements that produces a combined greater effect', 'CET6,IELTS', 4200, 'The synergy between visual subtitles and acoustic audio speeds up recall.', '画面字幕与原声音频的协同效应极大加速了记忆回想。'),
(31, 'inevitable', '/?n?ev?t?bl/', '/?n?ev?t?bl/', 'NULL', 'NULL', 'adj.', 'adj. 不可避免的，必然发生的', 'certain to happen; unavoidable', 'CET4,CET6', 1500, 'It was inevitable that they would meet.', '他们的相遇是必然的。'),
(34, 'incentive', '/?n?sent?v/', '/?n?sent?v/', 'NULL', 'NULL', 'n.', 'n. 激励，动机，刺激', 'a thing that motivates or encourages one to do something', 'CET4,CET6', 1650, 'Tax credits provide an incentive for green energy investment.', '税收抵免为绿色能源投资提供了有力激励。'),
(37, 'rude', '/ru?d/', '/ru?d/', 'NULL', 'NULL', 'adj.', 'adj. 粗鲁的，无礼的', 'offensively impolite or bad-mannered', 'CET4', 3100, 'Not to be rude, but didn\'t you say that last year?', '恕我直言，你去年不也这么说过？'),
(39, 'sector', '/?sekt?r/', '/?sekt?/', 'NULL', 'NULL', 'n.', 'n. 部门，领域，行业', 'an area or portion that is distinct from others', 'CET4,CET6', 950, 'The high-tech sector continues to drive regional growth.', '高新技术行业继续驱动着区域经济的增长。'),
(44, 'quote', '/kwo?t/', '/kw??t/', 'NULL', 'NULL', 'v./n.', 'v. 引用，引述 n. 引文', 'repeat or copy out a group of words from a text or speech', 'CET4', 1600, 'The author quotes several recent empirical studies.', '作者引用了最近的几项实证研究。'),
(47, 'positive', '/?pɑ?z?t?v/', '/?p?z?t?v/', 'NULL', 'NULL', 'adj.', 'adj. 积极的，正向的；确信的', 'consisting in or characterized by the presence of features', 'CET4', 790, 'Maintain a positive mindset during difficult tasks.', '在面对艰难任务时要保持积极的心态。'),
(48, 'boil', '/b??l/', '/b??l/', 'NULL', 'NULL', 'v.', 'v. 沸腾，煮沸', 'reach or cause to reach the temperature at which it bubbles', 'CET4', 2800, 'It made my blood boil to hear that.', '听到这个让我感觉热血沸腾。'),
(50, 'phenomenon', '/f??nɑ?m?n?n/', '/f??n?m?n?n/', 'NULL', 'NULL', 'n.', 'n. 现象；奇迹', 'a fact or situation that is observed to exist or happen', 'CET4,CET6', 1750, 'It\'s a phenomenon I\'ve never seen before.', '这是我以前从未见过的现象。'),
(79, 'scrutinize', '/\'skrutinaiz/', '/\'skrutinaiz/', 'https://dict.youdao.com/dictvoice?audio=scrutinize&type=2', 'https://dict.youdao.com/dictvoice?audio=scrutinize&type=1', 'vt.', 'vt.vi. 细看, 仔细检查, 审查, 细阅\\n[法] 细看, 细阅, 仔细检查', 'v to look at critically or searchingly, or in minute detail\\nv examine carefully for accuracy with the intent of verification', '考研, TOEFL, GRE, Collins-1★', 7785, 'Spenser\'s mother often scrutinizes him for every small mistake he makes.', 'Spenser的母亲经常会检视他犯的所有小错误。'),
(83, 'profound', '/prə\'faund/', '/prə\'faund/', 'https://dict.youdao.com/dictvoice?audio=profound&type=2', 'https://dict.youdao.com/dictvoice?audio=profound&type=1', 'a.', 'a. 极深的, 深厚的, 深刻的, 渊博的', 'a. showing intellectual penetration or emotional depth\\ns. of the greatest intensity; complete\\ns. coming from deep within one\\ns. situated at or extending to great depth; too deep to have been sounded or plumbed', 'CET6, 考研, TOEFL, IELTS, GRE, Collins-2★', 3735, 'The patient is in a state of profound stupor.', '患者现在处于深度昏迷状态。'),
(90, 'abandon', '/ә\'bændәn/', '/ә\'bændәn/', 'https://dict.youdao.com/dictvoice?audio=abandon&type=2', 'https://dict.youdao.com/dictvoice?audio=abandon&type=1', 'vt. / n.', 'vt. 放弃, 抛弃, 遗弃, 使屈从, 沉溺, 放纵\\nn. 放任, 无拘束, 狂热', 'n. the trait of lacking restraint or control; reckless freedom from inhibition or worry\\nv. forsake, leave behind\\nv. give up with the intent of never claiming again\\nv. stop maintaining or insisting on; of ideas or claims', '高考, CET4, CET6, 考研, TOEFL, GRE, Oxford3000, Collins-3★', 2182, 'The concept of abandon plays a significant role in modern academic discourse.', 'abandon这一概念在现代表达与学术语境中具有重要意义。'),
(95, 'abstract', '/\'æbstrækt/', '/\'æbstrækt/', 'https://dict.youdao.com/dictvoice?audio=abstract&type=2', 'https://dict.youdao.com/dictvoice?audio=abstract&type=1', 'a. / n. / vt.', 'a. 抽象的, 深奥的\\nn. 摘要, 抽象概念\\nvt. 摘要, 提炼, 使抽象化\\n[计] 摘录; 摘要; 抽象', 'v. consider a concept without thinking of a specific example; consider abstractly or theoretically\\nv. consider apart from a particular case or instance\\nv. give an abstract (of)\\na. existing only in the mind; separated from embodiment', '高考, CET4, CET6, 考研, TOEFL, IELTS, GRE, Collins-2★', 4007, 'I made an abstract of a book.', '我为一本书写了内容提要。'),
(99, 'accelerate', '/ək\'seləreit/', '/ək\'seləreit/', 'https://dict.youdao.com/dictvoice?audio=accelerate&type=2', 'https://dict.youdao.com/dictvoice?audio=accelerate&type=1', 'v.', 'v. 加速, 促进', 'v. move faster\\nv. cause to move faster', '高考, CET4, CET6, 考研, TOEFL, IELTS, GRE, Collins-2★', 4925, 'The car continued to accelerate.', '车子继续加速。'),
(100, 'access', '/\'ækses/', '/\'ækses/', 'https://dict.youdao.com/dictvoice?audio=access&type=2', 'https://dict.youdao.com/dictvoice?audio=access&type=1', 'n. / vt.', 'n. 通路, 入口, 接近, 进入, 使用权, 发作\\nvt. 访问, 存取, 接近, 使用\\n[计] 访问, 存取', 'n. the right to obtain or make use of or take advantage of something (as services or membership)\\nn. a way of entering or leaving\\nn. a code (a series of characters or digits) that must be entered in some way (typed or dialed or spoken) to get the use of something (a telephone line or a computer or a local area network etc.)\\nn. (computer science) the operation of reading or writing stored information', '高考, CET4, CET6, 考研, TOEFL, IELTS, GRE, Oxford3000, Collins-3★', 1113, 'Every new word mastered brings you closer to linguistic fluency.', '掌握的每一个新词都让你离语言流利更近一步。'),
(102, 'accommodate', '/ə\'kɒmədeit/', '/ə\'kɒmədeit/', 'https://dict.youdao.com/dictvoice?audio=accommodate&type=2', 'https://dict.youdao.com/dictvoice?audio=accommodate&type=1', 'vt. / vi.', 'vt. 使适应, 调和, 通融, 容纳, 向...提供\\nvi. 适应', 'v. provide with something desired or needed\\nv. have room for; hold without crowding\\nv. make (one thing) compatible with (another)', 'CET4, CET6, 考研, TOEFL, IELTS, GRE, Collins-2★', 3717, 'Sorry, I can\'t accommodate you.', '很抱歉没能帮到你。'),
(103, 'accommodation', '/ə.kɒmə\'deiʃən/', '/ə.kɒmə\'deiʃən/', 'https://dict.youdao.com/dictvoice?audio=accommodation&type=2', 'https://dict.youdao.com/dictvoice?audio=accommodation&type=1', 'n.', 'n. 膳宿, 预订铺位, 适应性调节, 调和, 贷款\\n[医] 调节(眼); 适应', 'n. a settlement of differences\\nn. in the theories of Jean Piaget: the modification of internal representations in order to accommodate a changing knowledge of reality\\nn. living quarters provided for public convenience\\nn. the act of providing something (lodging or seat or food) to meet a need', '高考, CET4, CET6, 考研, IELTS, Oxford3000, Collins-2★', 5369, 'Do you offer accommodation?', '您提供住宿吗？'),
(104, 'accompany', '/ə\'kʌmpəni/', '/ə\'kʌmpəni/', 'https://dict.youdao.com/dictvoice?audio=accompany&type=2', 'https://dict.youdao.com/dictvoice?audio=accompany&type=1', 'vt. / vi.', 'vt. 陪伴, 伴随, 补充, 为...伴奏\\nvi. 伴奏, 伴唱', 'v. go or travel along with', '高考, CET4, CET6, 考研, TOEFL, IELTS, GRE, Oxford3000, Collins-3★', 2438, 'Do I have the right to accompany you?', '我有权陪伴你吗？'),
(108, 'accumulate', '/ə\'kju:mjuleit/', '/ə\'kju:mjuleit/', 'https://dict.youdao.com/dictvoice?audio=accumulate&type=2', 'https://dict.youdao.com/dictvoice?audio=accumulate&type=1', 'v.', 'v. 积聚, 堆积', 'v. collect or gather', '高考, CET4, CET6, 考研, TOEFL, IELTS, GRE, Collins-2★', 5083, 'Dust had accumulated in the attic.', '阁楼上积了灰。'),
(109, 'accuracy', '/\'ækjurəsi/', '/\'ækjurəsi/', 'https://dict.youdao.com/dictvoice?audio=accuracy&type=2', 'https://dict.youdao.com/dictvoice?audio=accuracy&type=1', 'n.', 'n. 精确, 正确\\n[计] 准确度', 'n. the quality of being near to the true value\\nn. (mathematics) the number of significant figures given in a number', '高考, CET4, CET6, 考研, TOEFL, IELTS, GRE', 4076, 'There\'s no need to worry about accuracy this time; just eyeball it.', '现在精确度已经不重要了，你目测一下就好。'),
(110, 'accurate', '/\'ækjurət/', '/\'ækjurət/', 'https://dict.youdao.com/dictvoice?audio=accurate&type=2', 'https://dict.youdao.com/dictvoice?audio=accurate&type=1', 'a.', 'a. 正确的, 精确的\\n[经] 准确的, 精确的', 'a. conforming exactly or almost exactly to fact or to a standard or performing with total accuracy\\ns. (of ideas, images, representations, expressions) characterized by perfect conformity to fact or truth; strictly correct', 'CET4, CET6, 考研, TOEFL, IELTS, GRE, Oxford3000, Collins-3★', 2728, 'It\'s not your mother tongue, so your pronunciation will never be accurate.', '因为它不是你的母语，你的发音会永远不准。'),
(114, 'acquire', '/ə\'kwaiə/', '/ə\'kwaiə/', 'https://dict.youdao.com/dictvoice?audio=acquire&type=2', 'https://dict.youdao.com/dictvoice?audio=acquire&type=1', 'vt.', 'vt. 获得, 学到\\n[电] 目标锁定', 'v. locate (a moving entity) by means of a tracking system such as radar\\nv. win something through one\'s efforts', '高考, CET4, CET6, 考研, TOEFL, IELTS, Oxford3000, Collins-3★', 2063, 'Every new word mastered brings you closer to linguistic fluency.', '掌握的每一个新词都让你离语言流利更近一步。'),
(116, 'adapt', '/ə\'dæpt/', '/ə\'dæpt/', 'https://dict.youdao.com/dictvoice?audio=adapt&type=2', 'https://dict.youdao.com/dictvoice?audio=adapt&type=1', 'vt. / vi.', 'vt. 使适应, 改编\\nvi. 适应', 'v. make fit for, or change to suit a new purpose', '高考, CET4, CET6, 考研, TOEFL, IELTS, GRE, Oxford3000, Collins-2★', 2933, 'Bit by bit, I\'m adapting to the harsh climate here.', '我在慢慢习惯这苛刻的气候。'),
(120, 'adequate', '/\'ædikwət/', '/\'ædikwət/', 'https://dict.youdao.com/dictvoice?audio=adequate&type=2', 'https://dict.youdao.com/dictvoice?audio=adequate&type=1', 'a.', 'a. 适当的, 足够的\\n[法] 胜任的, 适当的, 充分的', 'a. having the requisite qualities or resources to meet a task\\ns. sufficient for the purpose\\ns. about average; acceptable', '高考, CET4, CET6, 考研, TOEFL, IELTS, GRE, Oxford3000, Collins-3★', 3297, 'We need not only adequate water but clean water.', '我们不仅需要充足的水，还需要干净的水。'),
(121, 'adjust', '/ə\'dʒʌst/', '/ə\'dʒʌst/', 'https://dict.youdao.com/dictvoice?audio=adjust&type=2', 'https://dict.youdao.com/dictvoice?audio=adjust&type=1', 'vt. / vi.', 'vt. 调整, 使适应于, 校准\\nvi. 适应于, 被调节, 相互熟悉而适应', 'v. alter or regulate so as to achieve accuracy or conform to a standard\\nv. adapt or conform oneself to new or different conditions\\nv. make correspondent or conformable\\nv. decide how much is to be paid on an insurance claim', '高考, CET4, CET6, 考研, TOEFL, IELTS, GRE, Oxford3000, Collins-3★', 2300, 'Every new word mastered brings you closer to linguistic fluency.', '掌握的每一个新词都让你离语言流利更近一步。'),
(130, 'affect', '/ə\'fekt/', '/ə\'fekt/', 'https://dict.youdao.com/dictvoice?audio=affect&type=2', 'https://dict.youdao.com/dictvoice?audio=affect&type=1', 'vt. / n.', 'vt. 影响, 感动, 假装, 模仿, 爱好, 倾向于\\nn. 自觉感情', 'n. the conscious subjective aspect of feeling or emotion\\nv. have an effect upon\\nv. act physically on; have an effect upon\\nv. have an emotional or cognitive impact upon', '高考, CET4, CET6, 考研, TOEFL, IELTS, Oxford3000, Collins-4★', 963, 'Every new word mastered brings you closer to linguistic fluency.', '掌握的每一个新词都让你离语言流利更近一步。'),
(142, 'alter', '/\'ɒ:ltə/', '/\'ɒ:ltə/', 'https://dict.youdao.com/dictvoice?audio=alter&type=2', 'https://dict.youdao.com/dictvoice?audio=alter&type=1', 'v.', 'v. 改变', 'v. make an alteration to\\nv. remove the ovaries of', 'CET4, CET6, 考研, TOEFL, IELTS, GRE, Oxford3000, Collins-3★', 2889, 'He\'s proposing a suggestion for altering the research method.', '他提出改革研究方法的意见。'),
(143, 'alternative', '/ɒ:l\'tə:nətiv/', '/ɒ:l\'tə:nətiv/', 'https://dict.youdao.com/dictvoice?audio=alternative&type=2', 'https://dict.youdao.com/dictvoice?audio=alternative&type=1', 'n. / a.', 'n. 两者择一, 供替代的选择\\na. 两者择一的, 供选择的\\n[计] 选择对象', 's. necessitating a choice between mutually exclusive possibilities\\ns. pertaining to unconventional choices', '高考, CET4, CET6, 考研, TOEFL, IELTS, Oxford3000, Collins-4★', 2073, 'Every new word mastered brings you closer to linguistic fluency.', '掌握的每一个新词都让你离语言流利更近一步。'),
(150, 'analyse', '/\'ænəlaiz/', '/\'ænəlaiz/', 'https://dict.youdao.com/dictvoice?audio=analyse&type=2', 'https://dict.youdao.com/dictvoice?audio=analyse&type=1', 'vt.', 'vt. 分析, 细察, 分解\\n[经] 分析', 'v consider in detail and subject to an analysis in order to discover essential features or meaning\\nv break down into components or essential features\\nv make a mathematical, chemical, or grammatical analysis of; break down into components or essential features\\nv subject to psychoanalytic treatment', 'CET4, CET6, 考研, Oxford3000, Collins-2★', 12788, 'Every new word mastered brings you closer to linguistic fluency.', '掌握的每一个新词都让你离语言流利更近一步。'),
(158, 'annual', '/\'ænjuəl/', '/\'ænjuəl/', 'https://dict.youdao.com/dictvoice?audio=annual&type=2', 'https://dict.youdao.com/dictvoice?audio=annual&type=1', 'n. / a.', 'n. 年刊, 年报\\na. 每年的, 一年一次的, 全年的, 一年生的', 'n. (botany) a plant that completes its entire life cycle within the space of a year\\nn. a reference book that is published regularly once every year\\na. completing its life cycle within a year\\ns. occurring or payable every year', '高考, CET4, 考研, TOEFL, IELTS, Oxford3000, Collins-4★', 1361, 'Every new word mastered brings you closer to linguistic fluency.', '掌握的每一个新词都让你离语言流利更近一步。'),
(159, 'anticipate', '/æn\'tisipeit/', '/æn\'tisipeit/', 'https://dict.youdao.com/dictvoice?audio=anticipate&type=2', 'https://dict.youdao.com/dictvoice?audio=anticipate&type=1', 'vt.', 'vt. 预期, 占先, 加速, 提前使用\\n[医] 提前出现, 先期发生', 'v. act in advance of; deal with ahead of time\\nv. realize beforehand\\nv. be excited or anxious about\\nv. be a forerunner of or occur earlier than', 'CET4, CET6, 考研, TOEFL, IELTS, GRE, Oxford3000, Collins-2★', 3187, 'I didn\'t anticipate that there would be a problem.', '我没料到会有问题。'),
(161, 'anxious', '/\'æŋʃəs/', '/\'æŋʃəs/', 'https://dict.youdao.com/dictvoice?audio=anxious&type=2', 'https://dict.youdao.com/dictvoice?audio=anxious&type=1', 'a.', 'a. 忧虑的, 发愁的, 渴望的', 's. eagerly desirous\\ns. causing or fraught with or showing anxiety', '高考, CET4, CET6, 考研, TOEFL, Oxford3000, Collins-3★', 3827, 'I\'m very anxious about my son\'s safety.', '我很担心我儿子的安全。'),
(163, 'apologize', '/ə\'pɒlədʒaiz/', '/ə\'pɒlədʒaiz/', 'https://dict.youdao.com/dictvoice?audio=apologize&type=2', 'https://dict.youdao.com/dictvoice?audio=apologize&type=1', 'vi.', 'vi. 道歉, 辩解', 'v. acknowledge faults or shortcomings or failing\\nv. defend, explain, clear away, or make excuses for by reasoning', '高考, CET4, TOEFL, GRE, Oxford3000, Collins-2★', 3739, 'I think it\'s you who should apologize to her.', '我觉得应该向她道歉的人是你。'),
(164, 'apparatus', '/.æpə\'reitəs/', '/.æpə\'reitəs/', 'https://dict.youdao.com/dictvoice?audio=apparatus&type=2', 'https://dict.youdao.com/dictvoice?audio=apparatus&type=1', 'n.', 'n. 装置, 器具, 器官\\n[化] 仪器; 器械', 'n. equipment designed to serve a specific function\\nn. (anatomy) a group of body parts that work together to perform a given function', 'CET4, CET6, 考研, IELTS, GRE, Collins-1★', 6978, 'Every new word mastered brings you closer to linguistic fluency.', '掌握的每一个新词都让你离语言流利更近一步。'),
