(24, '生活交际与出行实用口语', '涵盖社交聚会、旅行出行、就餐消费与日常居家高频生活实景词汇', 'COLLOQUIAL', '/covers/daily.jpg', 247, 1),
(25, '国际商务与职场沟通核心词', '外企办公、商务谈判、项目管理、财务商业与战略协同核心专业词汇', 'PROFESSIONAL', '/covers/business.jpg', 249, 1),
(26, '互联网与计算机技术专业词', '涵盖现代软件工程、算法与数据结构、分布式架构、人工智能与云计算前沿技术词汇', 'PROFESSIONAL', '/covers/tech.jpg', 236, 1),
(27, 'AWL 国际学术通用核心词汇 (Academic Word List)', 'Averil Coxhead 基于 350 万词学术语料库提炼的 570 组国际学术通用权威核心词族，科研与论文阅读必备黄金词表', 'ACADEMIC', '/covers/academic.jpg', 555, 1),
(28, '国际顶刊论文写作与学术研读高频词', '精选 Nature、Science 等顶刊论文假说验证、实证分析、逻辑推演与论文撰写高频动词及术语', 'ACADEMIC', '/covers/academic.jpg', 253, 1)
